#include <string>
#include <cctype>

class Solution {
public:
    int countKeyChanges(std::string s) {
        int ans = 0;
        for (size_t i = 1; i < s.size(); ++i) {
            if (std::tolower(s[i]) != std::tolower(s[i - 1])) ans++;
        }
        return ans;
    }
};

class Solution {
    public int countKeyChanges(String s) {
        s = s.toLowerCase();
        int ans = 0;
        for (int i = 1; i < s.length(); ++i) {
            if (s.charAt(i) != s.charAt(i - 1)) ans++;
        }
        return ans;
    }
}

var countKeyChanges = function(s) {
    s = s.toLowerCase();
    let ans = 0;
    for (let i = 1; i < s.length; ++i) {
        if (s[i] !== s[i - 1]) ans++;
    }
    return ans;
};
